#include "world_render.h"
#include <stdio.h>
#include <stdlib.h>
static int emit(void *unused,unsigned ref){(void)unused;printf(" %u",ref);return 0;}
int main(void){unsigned nx,nz,np,special,ncells;int minx,minz,maxx,maxz;if(scanf("%u%u%u%u%d%d%d%d%u",&nx,&nz,&np,&special,&minx,&minz,&maxx,&maxz,&ncells)!=9||!nx||!nz||nx*nz>1000000)return 1;TaxiWorldAsset w={.nx=nx,.nz=nz,.np=np,.special_count=special};w.cells=calloc((size_t)nx*nz,sizeof *w.cells);uint32_t *normal=calloc(np,sizeof *normal),*sprites=calloc(special,sizeof *sprites);if(!w.cells||!normal||!sprites)return 2;for(unsigned i=0;i<ncells;i++){unsigned x,z,n;if(scanf("%u%u%u",&x,&z,&n)!=3||x>=nx||z>=nz||n>65535)return 3;uint8_t *cell=calloc(28+2*n,1);if(!cell)return 4;for(unsigned b=0;b<4;b++)cell[b]=(uint8_t)(n>>(8*b));for(unsigned k=0;k<n;k++){unsigned ref;if(scanf("%u",&ref)!=1||ref>65535)return 5;cell[28+2*k]=(uint8_t)ref;cell[29+2*k]=(uint8_t)(ref>>8);}w.cells[(size_t)z*nx+x]=cell;}for(unsigned i=0;i<3;i++){unsigned generation=i<2?1:2;printf("%u",generation);if(taxi_world_render_visit_cached(&w,minx,minz,maxx,maxz,normal,np,sprites,special,generation,NULL,emit,NULL))return 6;puts("");}for(unsigned i=0;i<nx*nz;i++)free((void *)w.cells[i]);free(w.cells);free(normal);free(sprites);return 0;}
